def version_key(s):
    # Split the version string by dots and convert each component to an integer
    components = [int(part) for part in s.split('.')]
    # Remove trailing zero components
    while components and components[-1] == 0:
        components.pop()
    # Return the resulting tuple
    return tuple(components)
```

